71	// "A building block of 3 alike components is offered at a special base premium of 60 G."
72	const COMPONENT_TYPES = ["rune", "moonstone"];
73	const BLOCK_SIZE = 3;
74	const COMPONENT_BLOCK_PREMIUM = 60;
75	
76	const isCursed = (item: QuoteItem): boolean => item.cursed === true;
77	
78	const isLoyalCustomer = (customer: Customer): boolean =>
79	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
80	
81	const isHighlyEnchanted = (item: QuoteItem): boolean =>
82	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
83	
84	// Surcharges apply per item, as a percentage of that item's base premium.
85	const surchargeOn = (
86	  items: QuoteItem[],
87	  applies: (item: QuoteItem) => boolean,
88	  rate: number,
89	): number =>
90	  items.reduce(
91	    (sum, item) => sum + (applies(item) ? BASE_PREMIUMS[item.type] * rate : 0),
92	    0,
93	  );
94	
95	const quotePremium = (
96	  items: QuoteItem[],
97	  customer: Customer,
98	  isFollowUpContract: boolean,
99	): number => {
100	  const itemBase = items.reduce(
101	    (sum, item) => sum + BASE_PREMIUMS[item.type],
102	    0,
103	  );
104	  const blockDiscount = COMPONENT_TYPES.reduce((discount, type) => {
105	    const count = items.filter((item) => item.type === type).length;
106	    return count === BLOCK_SIZE
107	      ? discount + BLOCK_SIZE * BASE_PREMIUMS[type] - COMPONENT_BLOCK_PREMIUM
108	      : discount;
109	  }, 0);
110	  const policyBase = itemBase - blockDiscount;
111	  const curseSurcharge = surchargeOn(items, isCursed, CURSE_SURCHARGE_RATE);
112	  const highEnchantmentSurcharge = surchargeOn(
113	    items,
114	    isHighlyEnchanted,
115	    HIGH_ENCHANTMENT_SURCHARGE_RATE,
116	  );
117	  const firstInsurance = policyBase * FIRST_INSURANCE_RATE;
118	  const loyaltyDiscount = isLoyalCustomer(customer)
119	    ? policyBase * LOYALTY_DISCOUNT_RATE
120	    : 0;
121	  const followUpDiscount = isFollowUpContract
122	    ? policyBase * FOLLOW_UP_DISCOUNT_RATE
123	    : 0;
124	  return Math.ceil(
125	    policyBase +
126	      curseSurcharge +
127	      highEnchantmentSurcharge +
128	      firstInsurance -
129	      loyaltyDiscount -
130	      followUpDiscount +
131	      PROCESSING_FEE,
132	  );
133	};
