135	export const runScenario = (scenario: Scenario): ScenarioOutput => {
136	  const results = scenario.steps.map((step, index): StepResult => {
137	    if (step.op === "claim") {
138	      const policy = scenario.steps[step.policy] as QuoteStep;
139	      const insuranceSum = policy.items.reduce(
140	        (sum, item) => sum + 1000,
141	        0,
142	      );
143	      const cap = 2 * insuranceSum;
144	      const payout = step.incident.damages.reduce(
145	        (sum, damage) => sum + damage.amount - 100,
146	        0,
147	      );
148	      return { payout, remainingCap: cap - payout };
149	    }
150	    const isFollowUpContract = index > 0;
151	    return {
152	      premium: quotePremium(step.items, scenario.customer, isFollowUpContract),
153	    };
154	  });
155	  return { results };
156	};
