const DEDUCTIBLE = 100;
const CAP_MULTIPLIER = 2;
// Only sword-backed policies are claimed against so far; a per-type
// insurance-value table will be introduced when other types are tested.
const ITEM_INSURANCE_VALUE = 1000;

const settleClaim = (claim: ClaimStep, policy: QuoteStep): ClaimResult => {
  const insuranceSum = policy.items.length * ITEM_INSURANCE_VALUE;
  const cap = CAP_MULTIPLIER * insuranceSum;
  const payout = claim.incident.damages.reduce(
    (sum, damage) => sum + damage.amount - DEDUCTIBLE,
    0,
  );
  return { payout, remainingCap: cap - payout };
};

export const runScenario = (scenario: Scenario): ScenarioOutput => {
  const results = scenario.steps.map((step, index): StepResult => {
    if (step.op === "claim") {
      return settleClaim(step, scenario.steps[step.policy] as QuoteStep);
    }
